"use client";
import ClaudeColor from "@lobehub/icons/es/Claude/components/Color";
import { ContextWindowCompact as SharedContextWindowCompact } from "@ui/context-window";
import type { ContextWindowCompactProps } from "./context-window-compact-types";
/** Preserve the block's default provider logo; shared UI accepts a host icon. */
export function ContextWindowCompact(props: ContextWindowCompactProps) {
    const modelIcon = props.modelIcon ?? (/^claude(?:[-\s]|$)/i.test(props.data.session?.model ?? "") ? <ClaudeColor size={16}/> : undefined);
    return <SharedContextWindowCompact {...props} modelIcon={modelIcon}/>;
}

import type { ContextWindowData } from "../context-window-01/context-window-types";
/** Fixed reference snapshot. No model service is connected. */
export function createContextWindowCompactDemoData(): ContextWindowData {
    return {
        capacity: 200000, systemTokens: 4200, toolTokens: 12800,
        docs: [
            { id: "guide", title: "AGENTS.md", tokens: 6200 },
            { id: "tokens", title: "tokens.css", tokens: 12400 },
            { id: "components", title: "Component library", tokens: 27500 },
        ],
        history: [
            { id: "pinned", title: "Project instructions", tokens: 8600, pinned: true },
            { id: "conversation", title: "Current conversation", tokens: 100000 },
        ],
        memory: [{ id: "preferences", title: "Project preferences", tokens: 3900 }],
        session: { model: "claude-sonnet", turn: 24, name: "Component design" },
    };
}

export { ContextWindowCompact } from "./context-window-compact";
export { ContextWindowUsage } from "./context-window-usage";
export { createContextWindowCompactDemoData } from "./context-window-compact-demo-data";
export { contextWindowCompactEnglishLabels, contextWindowCompactZhLabels } from "./context-window-compact-labels";
export type { ContextWindowCompactLabels, ContextWindowCompactProps, ContextWindowUsageProps } from "./context-window-compact-types";
export type { ContextWindowData, ContextWindowItem } from "../context-window-01/context-window-types";
